-- Data Quality Validation SQL Script\n\n-- Null Value Validation\nSELECT * FROM property_data WHERE column_name IS NULL;\n\n-- Range Validation for Property Values\nSELECT * FROM property_data WHERE property_value < 0 OR property_value > 2500000;\n\n-- Range Classification of Property Values\nSELECT CASE\n    WHEN property_value BETWEEN 0 AND 750000 THEN '0-$750K'\n    WHEN property_value BETWEEN 750001 AND 1500000 THEN '$750K-$1.5M'\n    WHEN property_value BETWEEN 1500001 AND 2500000 THEN '$1.5M-$2.5M'\n    ELSE '> $2.5M'\nEND AS value_range, COUNT(*) AS count\nFROM property_data GROUP BY value_range;\n\n-- Referential Integrity Checks for Foreign Keys\nSELECT *\nFROM property_data p\nWHERE NOT EXISTS (SELECT 1 FROM foreign_table f WHERE f.foreign_key = p.foreign_key);\n\n-- Duplicate Detection\nSELECT column_name, COUNT(*)\nFROM property_data\nGROUP BY column_name\nHAVING COUNT(*) > 1;\n\n-- Data Type Validation\nSELECT * FROM property_data WHERE NOT (column_name IS NOT NULL AND data_type_check);\n\n-- Reconciliation Queries between Staging and Dimensional Tables\nSELECT *\nFROM staging_table s\nLEFT JOIN dimensional_table d ON s.primary_key = d.primary_key\nWHERE d.primary_key IS NULL;\n\n-- End of Data Quality Validation Script